from copy import deepcopy

def p(tc,en):return dict(tc=tc,en=en)
def route(label,nodes,edges,note):return dict(label=label,nodes=nodes,edges=edges,note=note)
def relation(a,verb,b,note):return dict(from_=a,verb=verb,to=b,note=note)
def rel(a,verb,b,note):return {'from':a,'verb':verb,'to':b,'note':note}
def clock(label,start,duration,note):return dict(label=label,start=start,duration=duration,note=note)

def apply(original, parts):
    panels=deepcopy(original)
    def refs(n,s,indices=None):
        blocks=next(v for v in parts[n]['sections'] if v['id']==s)['blocks']
        selected=blocks if indices is None else [blocks[i] for i in indices]
        return [deepcopy(r) for b in selected for r in b['refs']]
    def old(key):
        return next(v for ss in panels.values() for ps in ss.values() for v in ps if v['id']==key)
    def add(n,s,key,kind,title,**kw):
        v=dict(id=key,kind=kind,title=title,refs=kw.pop('refs',refs(n,s)),**kw)
        panels[n].setdefault(s,[]).append(v)
        return v
    def replace(key,kind,**kw):
        v=old(key);v['kind']=kind;v.update(kw);return v

    # Part 1: mechanism, purpose and scope; no mandatory three-stage sequence.
    stages=old('three-stages')
    stages['examples']=[
        route(p('同一犯罪得益：進入體系','Same criminal proceeds: entry'),[p('犯罪現金','Criminal cash'),p('存入戶口','Deposit into an account')],[p('存放','Placement')],p('教學例子：改變現金所在位置。','Teaching example: changes where the cash is held.')),
        route(p('同一犯罪得益：掩藏線索','Same proceeds: obscuring the trail'),[p('原來戶口','Original account'),p('多層戶口／交易','Layers of accounts / transactions')],[p('轉移、拆分','Move, split')],p('教學例子：增加追查來源的難度。','Teaching example: makes the origin harder to trace.')),
        route(p('同一犯罪得益：貌似合法','Same proceeds: apparent legitimacy'),[p('犯罪得益','Criminal proceeds'),p('貌似合法的投資／業務收益','Apparently lawful investment / business proceeds')],[p('重新呈現','Reappear as')],p('教學例子：外觀合法不會消除犯罪來源。','Teaching example: a lawful appearance does not erase criminal origin.'))]
    v=old('ml-tf-pf')
