    # Batch 1 (23 Oct 2026): list cards count the items of a source list; new comparison tables,
    # timelines and flows cover the places the exam tests most. Figures only; no point text changes.
    def card(n,s,key,title,items=None,groups=None,**kw):
        panel=dict(title=title,**kw)
        if groups:panel['groups']=[dict(title=g[0],items=[p(*x) for x in g[1]],**({'operator':g[2]} if len(g)>2 else {})) for g in groups]
        else:panel['items']=[p(*x) for x in items]
        if 'confuse' in kw:panel['confuse']=[p(*x) for x in kw['confuse']]
        return add(n,s,key,'checklist',**panel)
