    card(1,'legal-framework','osco-four',p('第1.20段：OSCO的四項功能','Paragraph 1.20: the four functions of OSCO'),[('賦予警方及海關人員調查有組織罪行及三合會活動的權力','Gives Police and Customs officers powers to investigate organized crime and triad activities'),('賦予法院沒收有組織及嚴重罪行得益的司法管轄權，並就被告人財產發限制令及押記令','Gives the courts jurisdiction to confiscate proceeds of organized and serious crimes and to issue restraint and charging orders'),('增訂一項有關可公訴罪行得益的洗錢罪行','Creates a laundering offence for the proceeds of indictable offences'),('容許法院在適當情況下收取違法者及罪行的資料，決定是否適宜加重判刑','Enables the courts, in appropriate cases, to receive information about an offender and an offence to decide on a greater sentence')],refs=refs(1,'legal-framework',[0]))
